/* ---- send: apply the database to a line's terminal (both devices on a line share one emulated database) */
function dmApplyArticle(dst,p,log){const keep=v=>Number(v)===0;
 dst.text=p.text;dst.life1=p.life1;dst.life2=p.life2;dst.tare=p.tarev>0&&B2.db.tare[p.tarev]!=null?B2.db.tare[p.tarev]:p.tare;dst.minw=p.minw;dst.maxw=p.maxw;dst.fixw=p.fixw;dst.pcs=p.pcs;dst.lseq=p.lseq;dst.grp=p.grp;dst.upi=p.upi;dst.country=p.country;dst.sprice=p.sprice;dst.nut=clone(p.nut||{});dst.sendfmt=p.sendfmt;dst.enabled=p.enabled;
 /* price: a 0.00 unit and special price leaves the terminal's own price (assumed: the 27/10 test labels printed £15.99 while Data Maintenance showed 0.00) */
 if(p.unit>0||p.sprice>0){dst.mode=p.ptype;dst.unit=p.unit;if(p.sprice>0&&p.ptype!=="Weight")dst.fixp=p.sprice}
 [["aut","aut"],["lab","lab"],["wc","wc"]].forEach(([a,b])=>{if(!keep(p[a]))dst[b]=Number(p[a])});
 dst.gtn=dst.gtn||[];for(let i=1;i<=10;i++){const g=Number(p.gt[i]);if(g===0)continue;dst.gtn[i]=g;const t=g===-1?"":B2.db.text[g];if(g>0&&t==null)log.push({t:`  PLU ${p.plu}: general text ${g} does not exist (text field ${i} left empty)`,c:"warn"});if(i===1)dst.txt1=g>0?g:0;else dst["tf"+i]=t||""}
 for(let i=1;i<=3;i++){const g=Number(p.dt[i]);if(g!==0)dst["dt"+i]=g}
 for(let i=1;i<=3;i++){if(!keep(p["logo"+i])){dst["logo"+i]=Number(p["logo"+i])===-1?0:Number(p["logo"+i]);if(i===1&&p.plu===7777&&Number(p.logo1)>0)B2.logoTried=true}if(!keep(p["cf"+i]))dst["cf"+i]=Number(p["cf"+i])===-1?0:Number(p["cf"+i])}
 for(let i=1;i<=5;i++){const v=String(p["cs"+i]??"0");if(v!=="0"&&v!=="")dst["cs"+i]=v}
 if(dst.d1==null)dst.d1="Packed on"}
function dmSendTo(id,X,log){const d=devLine(id);const k=d.line;const t=DBS[k]||(DBS[k]=freshDB());const P=B2.dm.pend[id]||{};const want=tab=>X.all||X.tabs[tab];const only=X.onlyChanged;let n=0;
 const pick=(tab,keys)=>only?keys.filter(x=>P[tab]&&P[tab].has(String(x))):keys;
 if(want("plu")){let keys=pick("plu",Object.keys(B2.db.plu));let c=0;keys.forEach(nn=>{const p=B2.db.plu[nn];if(!p)return;
   if(p.enabled===false&&X.delDis){if(t.plu[nn]){delete t.plu[nn];log.push({t:`  PLU ${nn} disabled: deleted in device`})}return}
   if(X.mode==="Only add new articles"&&t.plu[nn])return;
   const dst=t.plu[nn]||(t.plu[nn]=Object.assign(clone(p),{cf1:0,cs1:"0",logo1:0}));dmApplyArticle(dst,p,log);c++});
  if(X.delDel)Object.keys(t.plu).forEach(nn=>{if(!B2.db.plu[nn]){delete t.plu[nn];log.push({t:`  PLU ${nn} deleted in device`})}});
  log.push({t:`  Article data (GGDAT): ${c} record(s)`});n+=c;if(P.plu)P.plu.clear()}
 if(want("exc")){const ex=B2.exc.filter(x=>x.dev===id);ex.forEach(x=>{const tg=x.plu?[t.plu[x.plu]]:Object.values(t.plu);tg.forEach(p=>{if(!p)return;if(d.i===1){p.slave=p.slave||{};p.slave[x.field]=x.val}else p[x.field]=x.val})});log.push({t:`  Article Exceptions (GGDAT): ${ex.length} record(s)`});n+=ex.length}
 const tbl=(tab,label,srcObj,dstKey)=>{if(!want(tab))return;let keys=Object.keys(srcObj);
  if(X.req&&tab==="text"){const need=new Set();Object.values(B2.db.plu).forEach(p=>(p.gt||[]).forEach(g=>{if(g>0)need.add(String(g))}));Object.values(B2.db.wc).forEach(W=>W.cols.forEach(c=>{if(c.txt1>0)need.add(String(c.txt1))}));keys=keys.filter(x=>need.has(x))}
  keys=pick(tab,keys);t[dstKey]=t[dstKey]||{};keys.forEach(x=>{t[dstKey][x]=clone(srcObj[x])});if(tab==="text"){t.textfmt=t.textfmt||{};keys.forEach(x=>{t.textfmt[x]=(B2.dm.meta[x]||{}).fmt||"No"})}
  log.push({t:`  ${label}: ${keys.length} record(s)`});n+=keys.length;if(P[tab])P[tab].clear()};
 tbl("text","General texts (GGATX)",B2.db.text,"text");tbl("dtext","Date Texts (GGDTX)",B2.db.dtext,"dtext");tbl("stattxt","Static Texts (STATTXT)",B2.db.stattxt||{},"stattxt");tbl("code","Code Setup Rules (GGCAB)",B2.db.code,"code");
 tbl("auto","Automatic labeler parameters (AMPAR)",B2.dm.labDev["ap:"+dmName(id)]||B2.db.auto,"auto");tbl("label","Label parameters (GGETIKET)",B2.dm.labDev["lp:"+dmName(id)]||B2.db.label,"label");tbl("wc","Weight Classes (GGMINMAX)",B2.db.wc,"wc");
 if(want("pic"))log.push({t:"  Article Pictures: 0 record(s)"});if(want("scan"))log.push({t:"  Scan Code Setup Rules (GGSCAN): 0 record(s)"});if(want("tend"))log.push({t:"  Tendency regulation (TENDREG): 0 record(s)"});
 const lb=t.label&&Object.values(t.label);(lb||[]).forEach(l=>{if(l.layout&&!(t.layouts&&t.layouts[l.layout]))l._noLayout=true});
 B2.dm.sent[id]=nowStr();if(!X.onlyChanged)b2Ev("dmFullSend");t.dmSent=true;t.dmSentCons=ST[k]?ST[k].cons:null;if(B2.logoTried)t.logoTried=true;if(ST[k])withLine(k,()=>{S.wcJob=null;S.jobText={};S.jobOv=null;loadJob();S.ev.brain=true});
 return n}
function dmRunSend(devs,X){const M=B2.dm;const tabs=DM_TABLES.filter(([k])=>X.all||X.tabs[k]).length;const log=[];M.modal={k:"send",title:"Send data",log,busy:true,p:0};
 let i=0;const step=()=>{if(i>=devs.length){M.modal.busy=false;log.push({t:"Data transmission finished.",c:"ok"});b2Ev("dmSent");if(S)render();b2Render();return}
  const id=devs[i];const d=devLine(id);log.push({t:`Connecting to ${dmName(id)} (${d.ip}) …`});b2Render();
  setTimeout(()=>{const before=log.length;const n=dmSendTo(id,X,log);log.push({t:n?`${dmName(id)}: ${n} record(s) sent in ${tabs} table(s).`:`${dmName(id)}: nothing to send${X.onlyChanged?" (no changed records: untick \"Only send records that have been changed\" to send everything)":""}.`,c:n?"ok":"warn"});
   B2.transfers.unshift({at:new Date(),user:"Admin (Data Maintenance)",dev:dmName(id),what:"Send data: "+DM_TABLES.filter(([k])=>X.all||X.tabs[k]).map(x=>x[1].replace(/ \(.*/,"")).join(", "),res:n+" records"});
   M.modal.p=Math.round((i+1)/devs.length*100);i++;b2Render();setTimeout(step,reduced()?10:350)},reduced()?10:450)};step()}
/* ---- article save, with the Send format question (Yes = texts keep their own small format, No = the layout's field font) */
function dmSave(after){const M=B2.dm;if(M.mod==="Weight Classes"&&M.wc.work){dmWcSave();if(after)after();return}if(!M.dirty||!M.work){if(after)after();return}
 M.modal={k:"yn",title:"dataMaintenance",html:`Save article ${M.work.plu} and send the text format with it (Send format)?<br><span class="sm">Yes: the texts print in their own text format (the smaller font, as on the Co-op labels). No: the text fields print in the font set in the layout (bigger). Question wording assumed; effect from the notes of 27/10/2026.</span>`,yes:()=>dmCommit("Yes",after),no:()=>dmCommit("No",after),cancel:true}}
function dmCommit(fmt,after){const M=B2.dm;const w=M.work;const before=B2.db.plu[w.plu];w.sendfmt=fmt;w.dmMod=nowStr();w.dmBy="Admin";
 ["text","life1","life2","unit","lab","wc","aut","tare","minw","maxw","logo1","cf1","cs1"].forEach(f=>{if(String(before[f])!==String(w[f]))b2Audit("Data Maintenance","PLU "+w.plu,f,before[f],w[f])});
 if(JSON.stringify(before.gt)!==JSON.stringify(w.gt))b2Audit("Data Maintenance","PLU "+w.plu,"General texts",before.gt.slice(1).join(","),w.gt.slice(1).join(","));
 /* keep BRAIN2's literal text fields in step with the numbers */
 for(let i=2;i<=10;i++){const g=w.gt[i];if(g>0)w["tf"+i]=B2.db.text[g]||"";else if(g===-1)w["tf"+i]=""}if(w.gt[1]>0)w.txt1=w.gt[1];
 if(w.ptype!=="Weight"||w.unit>0)w.mode=w.ptype;
 B2.db.plu[w.plu]=w;M.work=null;M.dirty=false;dmTouch("plu",w.plu);if(B2.status[w.plu]==="Released")B2.status[w.plu]="Changed";b2Ev("dmArticleSaved");toast(`Article ${w.plu} saved. Send it: Upload / Download › Download Data.`);if(after)after()}
function dmWcSave(){const M=B2.dm;const n=M.wc.sel;b2Audit("Data Maintenance","Weight class "+n,"Saved","","");B2.db.wc[n]=M.wc.work;M.wc.work=null;dmTouch("wc",n);b2Ev("dmWcSaved");toast(`Weight class ${n} saved. Send it with Download Data.`)}
function dmGuard(fn){const M=B2.dm;if(M.dirty){M.modal={k:"yn",title:"dataMaintenance",html:`Article ${M.work.plu} has been changed. Save the changes?`,yes:()=>dmSave(fn),no:()=>{M.work=null;M.dirty=false;fn()},cancel:true};return}fn()}
function dmEdit(){const M=B2.dm;if(!M.work){M.work=clone(B2.db.plu[M.sel]);}M.dirty=true;return M.work}
function dmSetField(f,raw,isCk){const M=B2.dm;const w=dmEdit();let v=raw;
 const num=x=>{const n=parseFloat(String(x).replace(",","."));return isNaN(n)?0:n};
 if(f.includes(".")){const [a,b,c]=f.split(".");w[a]=w[a]||{};if(c!=null){w[a][b]=w[a][b]||{};w[a][b][c]=isCk?raw:raw}else w[a][b]=isCk?raw:(/^(portion|kj|kcal|fat|sat|carb|sug|fib|prot|salt|c1|c2|t1|t2)$/.test(b)?num(raw):raw);return}
 if(/^gt(\d+)$/.test(f)){w.gt[Number(f.slice(2))]=Math.round(num(v));return}if(/^dt(\d)$/.test(f)){w.dt[Number(f.slice(2))]=Math.round(num(v));return}
 if(f==="fixwk"){w.fixw=Math.round(num(v)*1000);return}if(f==="minwk"){w.minw=Math.round(num(v)*1000);return}if(f==="maxwk"){w.maxw=Math.round(num(v)*1000);return}if(f==="tarek"){w.tare=Math.round(num(v)*1000);return}
 if(/^(unit|sprice|ingp)$/.test(f)){w[f]=num(v);return}
 if(/^(life1|life2|aut|lab|wc|pcs|lseq|grp|tarev|logo\d|cf\d)$/.test(f)){w[f]=Math.round(num(v));return}
 if(f==="enabled"){w.enabled=!!isCk;return}
 w[f]=v}
function dmGet(f){const w=dmW();if(/^gt(\d+)$/.test(f))return w.gt[Number(f.slice(2))];if(/^dt(\d)$/.test(f))return w.dt[Number(f.slice(2))];if(f.includes(".")){const [a,b]=f.split(".");return(w[a]||{})[b]}return{fixwk:w.fixw/1000,minwk:w.minw/1000,maxwk:w.maxw/1000,tarek:w.tare/1000}[f]??w[f]}
